var $=django.jQuery;$(document).ready(function(){$(".clipboard").on("click",function(){var e=$(this),i=e.text();if(navigator.clipboard.writeText(i),e.hasClass("subst")){if(e.data("is-copying"))return;e.data("is-copying",!0),e.text("Copied!"),setTimeout(function(){e.text(i),e.data("is-copying",!1)},1200)}else e.find(".copied-badge").remove(),$('<div class="copied-badge">Copied</div>').hide().appendTo(e).fadeIn(200).delay(1200).fadeOut(400,function(){$(this).remove()})})});
